/**
 * Skill-linked scenarios: one per lesson or practice session that had no scenario of its own (skill === session title).
 * Same rules as the rest of the gym: three or more plausible options, a second-best option per decision, per-option feedback
 * with what it protects, what it costs and when it fits, claims only from verified sources already cited by that session.
 */
import type { ResponseOption, Scenario, ScenarioCategory } from './types';
type O = [text: string, quality: 0 | 1 | 2, feedback: string, protects: string, costs: string, fits: string];
const o = ([text, quality, feedback, protects, costs, fits]: O): ResponseOption => ({ text, quality, feedback, tradeoff: { protects, costs, fits } });
interface Def {
  id: string; skill: string; category: ScenarioCategory; context: 'everyday' | 'professional'; difficulty: 1 | 2 | 3; title: string;
  situation: string; facts: string[]; interpretations: string[]; emotionOptions: string[]; plausibleEmotions: number[];
  responses: O[]; claimIds: string[]; followUp?: { next: string[]; prompt: string; options: O[] };
}
const mk = (d: Def): Scenario => ({ ...d, responses: d.responses.map(o), followUp: d.followUp && { ...d.followUp, options: d.followUp.options.map(o) } });

